<script>
class SlidePresentation {
  constructor() {
    this.slides = Array.from(document.querySelectorAll('.slide'));
    this.currentSlide = 0;
    this.progressBar = document.querySelector('.progress-bar');
    this.nav = document.querySelector('.nav-dots');
    this.isScrolling = false;
    this.setupNavDots();
    this.setupIntersectionObserver();
    this.setupKeyboardNav();
    this.setupTouchNav();
    this.setupWheelNav();
    this.goToSlide(0, false);
  }
  setupIntersectionObserver() {
    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          this.currentSlide = this.slides.indexOf(entry.target);
          this.updateProgress();
        }
      });
    }, { threshold: 0.55 });
    this.slides.forEach(slide => observer.observe(slide));
  }
  setupKeyboardNav() {
    document.addEventListener('keydown', event => {
      if (['ArrowRight','ArrowDown','PageDown',' '].includes(event.key)) { event.preventDefault(); this.next(); }
      if (['ArrowLeft','ArrowUp','PageUp'].includes(event.key)) { event.preventDefault(); this.prev(); }
      if (event.key === 'Home') { event.preventDefault(); this.goToSlide(0); }
      if (event.key === 'End') { event.preventDefault(); this.goToSlide(this.slides.length - 1); }
    });
  }
  setupTouchNav() {
    let startY = 0;
    document.addEventListener('touchstart', event => { startY = event.touches[0].clientY; }, { passive: true });
    document.addEventListener('touchend', event => {
      const deltaY = startY - event.changedTouches[0].clientY;
      if (Math.abs(deltaY) > 45) deltaY > 0 ? this.next() : this.prev();
    }, { passive: true });
  }
  setupWheelNav() {
    document.addEventListener('wheel', event => {
      if (this.isScrolling || Math.abs(event.deltaY) < 20) return;
      this.isScrolling = true;
      event.deltaY > 0 ? this.next() : this.prev();
      setTimeout(() => { this.isScrolling = false; }, 650);
    }, { passive: true });
  }
  setupNavDots() {
    this.slides.forEach((_, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.setAttribute('aria-label', `Go to slide ${index + 1}`);
      button.addEventListener('click', () => this.goToSlide(index));
      this.nav.appendChild(button);
    });
  }
  goToSlide(index, smooth = true) {
    const target = Math.max(0, Math.min(index, this.slides.length - 1));
    this.currentSlide = target;
    this.slides[target].scrollIntoView({ behavior: smooth ? 'smooth' : 'auto', block: 'start' });
    this.slides[target].classList.add('visible');
    this.updateProgress();
  }
  next() { this.goToSlide(this.currentSlide + 1); }
  prev() { this.goToSlide(this.currentSlide - 1); }
  updateProgress() {
    const progress = ((this.currentSlide + 1) / this.slides.length) * 100;
    this.progressBar.style.width = `${progress}%`;
    Array.from(this.nav.children).forEach((button, index) => button.classList.toggle('active', index === this.currentSlide));
  }
}
window.addEventListener('DOMContentLoaded', () => new SlidePresentation());
</script>
